package dev.shadw.olympia.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.client.renderer.entity.state.LivingEntityRenderState;
import net.minecraft.resources.ResourceLocation;

/** Renders the Gorgon with its own model and texture. Generated by shadw-mod mob. */
public class GorgonRenderer extends MobRenderer<Gorgon, LivingEntityRenderState, GorgonModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("olympia", "textures/entity/gorgon.png");

	public GorgonRenderer(EntityRendererProvider.Context context) {
		super(context, new GorgonModel(context.bakeLayer(GorgonModel.LAYER)), 0.6F);
	}

	@Override
	public LivingEntityRenderState createRenderState() {
		return new LivingEntityRenderState();
	}

	@Override
	public ResourceLocation getTextureLocation(LivingEntityRenderState state) {
		return TEXTURE;
	}
}
